<script setup lang="ts">import type { EquipoEngraseListItem, EquipoFiltroDetalle, FiltroEquivalenciaRow } from '@/stores/dbequipos/engrase/filtrosEngrase.types';const props=defineProps<{equipo:EquipoEngraseListItem|null;filtros:EquipoFiltroDetalle[];equivalencias:Record<number,FiltroEquivalenciaRow[]>;selectedFiltroId:number|null;loading:boolean;error:string|null}>();defineEmits<{selectFiltro:[number];retry:[];backToEquipos:[]}>();</script><template><section class="panel"><button class="back" type="button" @click="$emit('backToEquipos')">← Equipos</button><template v-if="equipo"><header><div><p class="eyebrow">{{equipo.tipo_equipo}}</p><h2>{{equipo.codigo}}</h2><p>Modelo: {{equipo.subtipo||'Sin modelo'}} · {{equipo.etapas.map(x=>x.nombre).join(', ')||'Sin etapa'}}</p></div><b class="status" :class="equipo.estado">{{equipo.estado}}</b></header><div class="metrics"><div><span>Total filtros</span><b>{{filtros.length}}</b></div><div><span>Con equivalencias</span><b>{{filtros.filter(x=>(equivalencias[x.filtro_id]??[]).length).length}}</b></div><div><span>En lista de compras</span><b>{{filtros.filter(x=>x.filtro.esta_en_lista_compras).length}}</b></div></div><p v-if="loading" class="empty">Cargando filtros…</p><p v-else-if="error" class="empty">{{error}} <button @click="$emit('retry')">Reintentar</button></p><p v-else-if="!filtros.length" class="empty">Este equipo no tiene filtros asignados.</p><div v-else class="cards"><button v-for="filtro in filtros" :key="filtro.id" class="card" :class="{selected:selectedFiltroId===filtro.id}" :aria-selected="selectedFiltroId===filtro.id" @click="$emit('selectFiltro',filtro.id)"><strong>{{filtro.tipoFiltro.nombre}}</strong><dl><dt>Código original</dt><dd>{{filtro.filtro.codigo}}</dd><dt>Cantidad</dt><dd>x{{filtro.cantidad}}</dd><dt>Equivalencias</dt><dd>{{(equivalencias[filtro.filtro_id]??[]).length}}</dd><dt>En lista de compras</dt><dd>{{filtro.filtro.esta_en_lista_compras?'Sí':'No'}}</dd></dl></button></div></template><p v-else class="empty">Seleccione un equipo para ver sus filtros.</p></section></template><style scoped>.panel{min-height:0;padding:1.1rem;border:1px solid #e6edf7;border-radius:1rem;background:#fff;overflow:auto}.back{display:none;color:#0759e8;font-size:.8rem}.panel header{display:flex;justify-content:space-between;align-items:start}.eyebrow{color:#0759e8;font-size:.72rem;font-weight:800}.panel h2{margin:.15rem 0;color:#14265a;font-size:1.25rem}.panel p{color:#64748b;font-size:.78rem}.status{text-transform:uppercase;font-size:.62rem;padding:.3rem .4rem;border-radius:.35rem}.status.activo{color:#15803d;background:#dcfce7}.status.descartado{color:#dc2626;background:#fee2e2}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:.65rem;margin:1rem 0}.metrics div{padding:.75rem;border:1px solid #e6edf7;border-radius:.65rem}.metrics span{display:block;color:#63749a;font-size:.68rem}.metrics b{display:block;margin-top:.3rem;color:#14265a;font-size:1.35rem}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:.7rem}.card{padding:.9rem;border:1px solid #e6edf7;border-radius:.7rem;text-align:left;color:#172554}.card.selected{border-color:#2563eb;background:#eff6ff}.card dl{display:grid;grid-template-columns:1fr auto;gap:.5rem;margin:.8rem 0 0;font-size:.72rem}.card dt{color:#65779e}.card dd{margin:0;font-weight:700}.empty{padding:2rem;text-align:center}.empty button{color:#0759e8;font-weight:700}@media(max-width:760px){.back{display:block}.metrics{grid-template-columns:1fr}.cards{grid-template-columns:1fr}}</style>
